```cpp
big_uint big_step(big_uint a, bool add)
{
    for (auto& x : a)
    {
        const std::uint32_t old = x;
        x = add ? x + 1 : x - 1;
        if ((add && x > old) || (!add && x < old))
        {
            break;
        }
    }
    if (add && (a.empty() || a.back() == 0))
    {
        a.push_back(1);
    }
    big_trim(a);
    return a;
}
```

