std::size_t significant_digits(const std::string& s)
{
    std::string digits;
    for (const char c : s)
    {
        if (c == 'e' || c == 'E')
        {
            break;
        }
        if (c >= '0' && c <= '9' && !(digits.empty() && c == '0'))
        {
            digits += c;
        }
    }
    while (!digits.empty() && digits.back() == '0')
    {
        digits.pop_back();
    }
    return digits.size();
}
```

